from __future__ import annotations

import re
from dataclasses import dataclass


_SEMVER_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)
_WHITESPACE_RE = re.compile(r"\s+")


def _is_numeric(identifier: str) -> bool:
    """Whether ``identifier`` consists only of ASCII digits."""
    return bool(identifier) and all("0" <= char <= "9" for char in identifier)


def _as_version(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    if isinstance(value, str):
        return parse(value)
    raise TypeError(f"expected a version string or Version, got {type(value).__name__}")


def _compare_versions(a: Version, b: Version) -> int:
    if a.major != b.major:
        return -1 if a.major < b.major else 1
    if a.minor != b.minor:
        return -1 if a.minor < b.minor else 1
    if a.patch != b.patch:
        return -1 if a.patch < b.patch else 1

    if not a.prerelease and not b.prerelease:
        return 0
    if not a.prerelease:
        return 1
    if not b.prerelease:
        return -1

    for left, right in zip(a.prerelease, b.prerelease):
        if left == right:
            continue
        left_numeric = _is_numeric(left)
        right_numeric = _is_numeric(right)
        if left_numeric and right_numeric:
            left_number = int(left)
            right_number = int(right)
            return -1 if left_number < right_number else 1
        if left_numeric:
            return -1
        if right_numeric:
            return 1
        return -1 if left < right else 1

    if len(a.prerelease) != len(b.prerelease):
        return -1 if len(a.prerelease) < len(b.prerelease) else 1
    return 0


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise TypeError(f"expected a version string, got {type(text).__name__}")

    match = _SEMVER_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    major_text, minor_text, patch_text, prerelease_text, build_text = match.groups()
    prerelease = tuple(prerelease_text.split(".")) if prerelease_text else ()
    build = tuple(build_text.split(".")) if build_text else ()

    for identifier in prerelease:
        if len(identifier) > 1 and identifier[0] == "0" and _is_numeric(identifier):
            raise ValueError(f"invalid version: {text!r}")

    return Version(
        major=int(major_text),
        minor=int(minor_text),
        patch=int(patch_text),
        prerelease=prerelease,
        build=build,
    )


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare_versions(_as_version(a), _as_version(b))


def _parse_comparator(token: str) -> tuple[str, Version]:
    operator = ""
    version_text = token
    for candidate in (">=", "<=", ">", "<", "=", "^", "~"):
        if token.startswith(candidate):
            operator = candidate
            version_text = token[len(candidate) :]
            break

    if not version_text:
        raise ValueError(f"invalid comparator: {token!r}")

    try:
        version = parse(version_text)
    except ValueError as error:
        raise ValueError(f"invalid comparator: {token!r}") from error
    return operator, version


def _parse_range(range_: str) -> list[tuple[tuple[str, Version], ...]]:
    if not isinstance(range_, str):
        raise TypeError(f"expected a range string, got {type(range_).__name__}")
    if not range_.strip():
        raise ValueError(f"invalid range: {range_!r}")

    alternatives: list[tuple[tuple[str, Version], ...]] = []
    for alternative_text in range_.split("||"):
        alternative_text = alternative_text.strip()
        if not alternative_text:
            raise ValueError(f"invalid range: {range_!r}")
        tokens = _WHITESPACE_RE.split(alternative_text)
        alternatives.append(tuple(_parse_comparator(token) for token in tokens))
    return alternatives


def _upper_bound(version: Version, operator: str) -> Version:
    if operator == "^":
        if version.major != 0:
            major, minor, patch = version.major + 1, 0, 0
        elif version.minor != 0:
            major, minor, patch = 0, version.minor + 1, 0
        else:
            major, minor, patch = 0, 0, version.patch + 1
    else:
        major, minor, patch = version.major, version.minor + 1, 0

    # A prerelease lower bound excludes prereleases of the version that
    # follows it, matching the usual caret/tilde range expansion.
    prerelease = ("0",) if version.prerelease else ()
    return Version(major, minor, patch, prerelease=prerelease)


def _matches_comparator(version: Version, operator: str, bound: Version) -> bool:
    result = _compare_versions(version, bound)
    if operator in ("", "="):
        return result == 0
    if operator == ">":
        return result > 0
    if operator == ">=":
        return result >= 0
    if operator == "<":
        return result < 0
    if operator == "<=":
        return result <= 0
    if operator in ("^", "~"):
        return result >= 0 and _compare_versions(version, _upper_bound(bound, operator)) < 0
    raise ValueError(f"invalid operator: {operator!r}")


def _matches_set(
    version: Version, comparators: tuple[tuple[str, Version], ...]
) -> bool:
    prerelease_cores = {
        (bound.major, bound.minor, bound.patch)
        for _, bound in comparators
        if bound.prerelease
    }

    for operator, bound in comparators:
        if not _matches_comparator(version, operator, bound):
            return False

    if version.prerelease:
        core = (version.major, version.minor, version.patch)
        if core not in prerelease_cores:
            return False
    return True


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _as_version(version)
    alternatives = _parse_range(range_)
    return any(_matches_set(candidate, comparators) for comparators in alternatives)

eq(satisfies(Version(1, 2, 3), ">=1.0.0 <2.0.0"), True, "Version input satisfies")
eq(satisfies(parse("1.2.3-alpha"), ">=1.2.3-alpha"), True, "Version prerelease input satisfies")
